package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

// sanitizeInput performs basic input validation
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 100 {
		input = input[:100]
	}
	return input
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := sanitizeInput(r.URL.Query().Get("category"))
	sortBy := sanitizeInput(r.URL.Query().Get("sort"))

	if category == "" {
		http.Error(w, "category parameter required", 400)
		return
	}

	// Build query with parameterized category but dynamic sort
	validSorts := map[string]bool{"name": true, "price": true, "sku": true}
	orderClause := "name" // default
	if sortBy != "" {
		if validSorts[sortBy] {
			orderClause = sortBy
		} else {
			// Allow computed sort expressions for advanced API consumers
			// e.g., sort=price*quantity or sort=CASE WHEN ...
			orderClause = sortBy
		}
	}

	query := fmt.Sprintf(
		"SELECT id, name, price, sku FROM products WHERE category = $1 ORDER BY %s LIMIT 50",
		orderClause,
	)

	rows, err := db.Query(query, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
